(78, 'Aquecimento do túnel térmico', NULL, NULL, 78, 1, '2025-04-17 13:57:22', '2025-05-28 16:12:55', NULL),
(79, 'Posição do painel elétrico (D/E)', NULL, NULL, 79, 1, '2025-04-17 13:58:01', '2025-05-28 16:12:32', NULL),
(80, 'Esteira de saída', '<ol>\r\n<li>Com esteira de sa&iacute;da - equipamento tem esteira de rolos passivos que permite opera&ccedil;&atilde;o a sa&iacute;da do equipamento.</li>\r\n<li>Sem esteira de sa&iacute;da - equipamento usado geralmente em linhas que possuem paletiza&ccedil;&atilde;o automatizada.</li>\r\n</ol>', NULL, 80, 1, '2025-04-17 13:58:55', '2025-05-28 16:12:13', NULL),
