(111, 'Alinhador de rótulos', '<ol>\r\n<li>Opcional utilizado para melhoria da qualidade da aplica&ccedil;&atilde;o.</li>\r\n<li>Tamb&eacute;m indicado para m&aacute;quinas de velocidade alta.</li>\r\n</ol>', NULL, 111, 1, '2025-05-02 10:45:51', '2025-05-28 16:25:06', NULL),
(112, 'Segundo suporte de bobina', '<ol>\r\n<li>Diminui o tempo de parada para troca de r&oacute;tulo.</li>\r\n</ol>', NULL, 112, 1, '2025-05-02 10:48:00', '2025-05-28 16:25:28', NULL),
(113, 'Controle de ausência de rótulo', '<ol>\r\n<li>Item opcional usado na garantia da qualidade.</li>\r\n<li>Destinado para detectar falta de r&oacute;tulos nos frascos.</li>\r\n<li>Existem duas vers&otilde;es do sistema:\r\n<ol>\r\n<li>Sozinho, funcionando como simples alarme - alarme informa a suspeita e para a rotuladora, o operador procura a frente do sensor o frasco desconforme.</li>\r\n<li>Em conjunto com o rejeito autom&aacute;tico - com essa op&ccedil;&atilde;o o sistema pode:\r\n<ol>\r\n<li>Descartar o frasco suspeito.</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>', NULL, 113, 1, '2025-05-02 10:49:26', '2025-05-28 16:25:39', NULL),
