(193, 'Posición del tablero eléctrico (D/E)', NULL, NULL, 79, 2, '2025-10-21 13:54:16', '2025-10-21 13:54:16', NULL),
(194, 'Cinta de salida', '<ol>\r\n<li>Con cinta de salida - equipo tiene cinta de rodillos pasivos que permite operaci&oacute;n en la salida del equipo.</li>\r\n<li>Sin cinta de salida - equipo usado generalmente en l&iacute;neas que poseen paletizaci&oacute;n automatizada.</li>\r\n</ol>', NULL, 80, 2, '2025-10-21 13:56:13', '2025-10-21 13:58:49', NULL),
