(223, 'Alineador de etiquetas', '<ol>\r\n<li>Opcional utilizado para mejora de la calidad de aplicaci&oacute;n.</li>\r\n<li>Tambi&eacute;n indicado para m&aacute;quinas de alta velocidad.</li>\r\n</ol>', NULL, 111, 2, '2025-10-22 08:49:32', '2025-10-22 08:50:08', NULL),
(224, 'Segundo soporte de bobina', '<ol>\r\n<li>Reduce el tiempo de parada para cambio de etiqueta.</li>\r\n</ol>', NULL, 112, 2, '2025-10-22 08:52:06', '2025-10-22 08:52:06', NULL),
(225, 'Control de ausencia de etiqueta', '<ol>\r\n<li>Art&iacute;culo opcional utilizado para garantizar la calidad.</li>\r\n<li>Destinado a detectar falta de etiquetas en los frascos.</li>\r\n<li>Existen dos versiones del sistema:<br>\r\n<ol>\r\n<li>Individual, funcionando como alarma simple - la alarma informa la sospecha y detiene la etiquetadora, el operador busca el frasco no conforme frente al sensor.</li>\r\n<li>En conjunto con el rechazo autom&aacute;tico - con esta opci&oacute;n el sistema puede:\r\n<ol>\r\n<li>Descartar el frasco sospechoso.</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>', NULL, 113, 2, '2025-10-22 08:54:42', '2025-10-22 08:55:36', NULL),
